//! ✅️ Owned field rules inspect bounded fragments from the original input and genuine target row.
use super::*;
/// 📏️ Authored policies declare fixed inspection cost and retain all finite validation state explicitly.
pub trait OriginalValueRule:Send+Sync+'static{type Input:Send+Sync;type Row:EntityRow;type State:Copy+Send;const INSPECTION_BYTES:usize;fn initial()->Self::State;fn len(input:&Self::Input)->usize;fn valid_len(length:usize,row:&Self::Row)->bool;fn inspect(input:&Self::Input,index:usize,row:&Self::Row,original:&EnergyModelSnapshot,state:&mut Self::State)->bool;fn finish(_:Self::State,_:&Self::Row)->bool{true}}
pub struct ValueValidation<P:OriginalValueRule>{input:Option<RetainedCloneBinding>,row:Option<RetainedCloneBinding>,original:Option<RetainedCloneBinding>,offset:usize,state:P::State,phase:u8,result:Option<Option<RowOutcome>>,closing:bool}
impl<P:OriginalValueRule> ValueValidation<P>{pub fn new()->Self{Self{input:None,row:None,original:None,offset:0,state:P::initial(),phase:0,result:None,closing:false}}fn fixed()->usize{2*size_of::<usize>()+2*size_of::<P::State>()+3}fn end(&self,input:&P::Input,body:usize)->usize{self.offset+(body.saturating_sub(Self::fixed())/P::INSPECTION_BYTES.max(1)).min(P::len(input).saturating_sub(self.offset))}}
impl<P:OriginalValueRule> OwnedRowValidation<P::Input,P::Row> for ValueValidation<P>{
 fn demand(&self,input:RetainedCloneRef<'_,P::Input>,_:RetainedCloneRef<'_,u32>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,row:RetainedCloneRef<'_,P::Row>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.result.is_some(){return Err(invalid());}input.check_binding(&self.input)?;row.check_binding(&self.row)?;original.check_binding(&self.original)?;match self.phase{0=>nested(scalar(input.binding_copy_bytes()),1),1=>nested(scalar(row.binding_copy_bytes()),1),2=>nested(scalar(original.binding_copy_bytes()),1),3|5=>Ok(scalar(Self::fixed())),4=>Ok(scalar(Self::fixed()+(self.end(input.get(),body)-self.offset)*P::INSPECTION_BYTES)),_=>Err(invalid())}}
 fn advance(&mut self,input:RetainedCloneRef<'_,P::Input>,key:RetainedCloneRef<'_,u32>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,row:RetainedCloneRef<'_,P::Row>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(input,key,original,row,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{0=>{p=add(input.bind(&mut self.input,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=1;},1=>{p=add(row.bind(&mut self.row,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{p=add(original.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=3;},3=>{if P::valid_len(P::len(input.get()),row.get()){self.phase=4;}else{self.result=Some(Some(RowOutcome::Invalid));}},4=>{let end=self.end(input.get(),body);while self.offset<end{if !P::inspect(input.get(),self.offset,row.get(),original.get(),&mut self.state){self.result=Some(Some(RowOutcome::Invalid));break;}self.offset+=1;}if self.result.is_none()&&self.offset==P::len(input.get()){self.phase=5;}},5=>{self.result=Some((!P::finish(self.state,row.get())).then_some(RowOutcome::Invalid));},_=>return Err(invalid())}Ok(if self.result.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<Option<RowOutcome>>{self.result}
 fn begin_close(&mut self){self.closing=true;}
}
impl<P:OriginalValueRule> CursorClose for ValueValidation<P>{fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}RetainedCloneBinding::close_demand(if self.input.is_some(){&self.input}else if self.row.is_some(){&self.row}else{&self.original},body)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let s=RetainedCloneBinding::close_one(if self.input.is_some(){&mut self.input}else if self.row.is_some(){&mut self.row}else{&mut self.original},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}fn terminal_is_empty(&self)->bool{self.closing&&self.input.is_none()&&self.row.is_none()&&self.original.is_none()}}
impl<P:OriginalValueRule> Drop for ValueValidation<P>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original value rule retains input, target row or document binding");}}
